root = Path(__file__).parent / 'translations/ro/full/chunks'
translations = {
    't000001': 'Universul Star Wars',
    't000002': 'Universul Star Wars',
    't000003': 'Introducere',
    't000004': 'În centrul sagăi Star Wars se află povestea complicată a familiei Skywalker, desfășurată de-a lungul a trei trilogii și constituind firul principal care leagă întregul univers. Această galaxie întinsă este definită de câteva elemente esențiale care îi modelează mitologia și poveștile. Cel mai important este Forța, un câmp de energie mistică ce străbate galaxia și leagă toate ființele vii. Forța are puterea de a crea și de a distruge deopotrivă și este mânuită de nobilii Jedi și de întunecații Sith, reprezentând lupta neîncetată dintre bine și rău. Alături de Forță, tehnologia avansată este un semn distinctiv al universului Star Wars. De la săbiile laser emblematice ale cavalerilor Jedi până la nenumăratele nave stelare care străbat galaxia, tehnologia joacă un rol esențial în poveste. Droizi precum R2-D2 și C-3PO adaugă personalitate și profunzime, arătând amestecul de ingeniozitate mecanică și rezonanță emoțională care caracterizează seria.',
    't000005': 'Galaxia este populată și de o mare diversitate de specii extraterestre, fiecare cu propriile culturi, istorii și civilizații. Această varietate îmbogățește povestea și reflectă complexitatea lumii noastre, explorând unitatea și diversitatea. Conflictele dintre aceste culturi duc adesea la bătălii epice, iar războaiele galactice de mare amploare formează fundalul multora dintre momentele hotărâtoare ale sagăi. În esență, Star Wars urmează călătoria eroului, o structură narativă fără vârstă, în care personajele cresc, trec prin încercări și se transformă. Acest arc le permite spectatorilor să se apropie de personaje când ele înfruntă probe care le pun la încercare hotărârea și convingerile. Pătrunzând mai adânc în universul Star Wars, descoperim nu doar fundamentele filosofice bogate ale sagăi, ci și țesătura complicată de culturi și societăți care locuiesc această galaxie foarte, foarte îndepărtată.',
    't000006': 'Felul aparte în care seria abordează știința și tehnologia ne invită să ne gândim la viitor, la etică și la posibilele urmări ale progreselor noastre. Aventurile epice devenite sinonime cu Star Wars fac mai mult decât să distreze: inspiră, provoacă și răsună în mințile mai multor generații de spectatori, gânditori și creatori, lăsând o urmă adâncă în cultura populară și modelând felul în care spunem povești. Prin îmbinarea mitologiei, filosofiei și tehnologiei de vârf, Star Wars continuă să aprindă imaginația și să provoace reflecții despre locul nostru în univers.',
    't000007': 'Midiclorienii și Forța: ce ar însemna pentru omenirea de astăzi?',
    't000008': 'Imaginați-vă o lume în care știința noastră ar descoperi într-o zi ceva ce părea cândva pură fantezie: midiclorienii. Aceste organisme microscopice, răspunzătoare în Star Wars de legătura unei persoane cu Forța, ar putea transforma complet felul în care percepem viața, universul și chiar propria existență. Cum ar arăta lumea noastră dacă unii dintre noi ar afla dintr-odată că au o legătură mai profundă cu tot ce îi înconjoară? Cum s-ar potrivi o asemenea descoperire într-o epocă dominată de tehnologie și inteligență artificială? Dacă midiclorienii ar fi reali, aceasta ar însemna că fiecare ființă vie posedă o energie care o leagă de un întreg universal, așa cum Forța leagă toate lucrurile în Star Wars. Dar ce ar însemna asta pentru noi ca specie? Ar schimba felul în care abordăm religia, știința și filosofia vieții?',
    't000009': 'De secole, oamenii caută răspunsuri la întrebări fundamentale: „Cine suntem?” și „Care este rostul nostru în univers?” Dacă am descoperi că un anumit număr de midiclorieni din sânge ne-ar oferi acces la o formă mai înaltă de percepție și interacțiune cu energia universală, întreaga noastră viziune asupra existenței s-ar schimba. Ne-am mai sprijini doar pe tehnologie pentru a înțelege universul sau ne-am îndrepta spre ceva mai profund, mai spiritual? Într-o vreme în care tehnologia pare să ne îndepărteze de noi înșine și de legăturile umane autentice, o asemenea descoperire ar putea aprinde o renaștere a spiritualității și a sentimentului de interconectare. Omenirea s-ar putea întreba: „Suntem într-adevăr doar biologie și tehnologie sau există ceva mai mult, ascuns în natura noastră?” Cum ar răspunde știința modernă la descoperirea unor midiclorieni reali? Oamenii de știință ar fi probabil primii care ar studia aceste microentități, încercând să le înțeleagă funcția.',
    't000010': 'În Star Wars, Forța este o energie mistică, dar dacă tehnologia avansată ar putea oferi o explicație științifică acestei legături universale? Am putea măsura Forța? Am putea învăța să o controlăm? Sau, așa cum sugerează filmele, Forța ar rămâne dincolo de limitele controlului tehnologic? Ar apărea repede și o altă întrebare: „Ce înseamnă să ai mai mulți midiclorieni decât ceilalți?” Într-o societate deja împărțită de inegalități, descoperirea că unii oameni ar putea avea mai multă „Forță” decât alții ar putea duce la noi forme de elitism. Cei cu un număr mare de midiclorieni ar deveni liderii noștri spirituali și politici, asemenea cavalerilor Jedi din galaxia Star Wars? Sau ne-am teme că această putere ar putea fi folosită greșit, așa cum Sith au manipulat Forța pentru control și dominație? E greu de imaginat schimbările sociale pe care le-ar aduce o asemenea descoperire. Am vedea o trezire spirituală globală, în care omenirea ar învăța să trăiască în armonie cu Forța și să-și regăsească legătura cu natura și universul?',
    't000011': 'Sau, dimpotrivă, am asista la o luptă pentru putere, în care cei cu însușiri speciale ar fi vânați, exploatați ori venerați? O lume în care unii ar putea manipula realitatea prin Forță ar fi fascinantă, dar și primejdioasă. Ar putea oamenii găsi un echilibru între tehnologie și Forță, între ceea ce ne face umani și ceea ce ne leagă de ceva mai mare? „Am folosi aceste noi puteri pentru binele comun sau am cădea în capcana căutării puterii și controlului, așa cum s-a întâmplat în Star Wars?” Această întrebare ar deveni esențială pentru modelarea viitorului nostru. Într-o lume condusă tot mai mult de tehnologie, descoperirea Forței ne-ar putea aminti că suntem mai mult decât suma progreselor tehnologice. În secolul al XXI-lea, mulți simt că ne îndepărtăm de tradițiile culturale, de natură și chiar de propria esență umană. Dar, dacă am descoperi că putem accesa Forța, ea ne-ar putea oferi o șansă unică de a ne regăsi pe noi înșine și lumea din jur.',
    't000012': 'Nu am mai căuta doar soluții tehnologice la problemele noastre, ci și răspunsuri spirituale și emoționale. Așadar, ce ar însemna această descoperire pentru omenire? Ne-ar face mai buni? Ar scoate la iveală ceea ce avem mai curat și mai nobil sau ne-ar amplifica laturile întunecate? Răspunsul ar depinde de felul în care am alege să folosim Forța. Această nouă realitate ar putea deschide calea unei epoci de aur a înțelepciunii și compasiunii sau, așa cum ne avertizează istoria și ficțiunea, ar putea duce la conflicte și dezbinare. Dacă midiclorienii și Forța ar deveni realitate în lumea noastră, urmările pentru omenire ar fi imense. Ne-am confrunta cu întrebări filosofice și morale pe care nici tehnologia avansată nu le-ar putea rezolva. O asemenea descoperire ar putea redefini ce înseamnă să fii om și ne-ar putea da șansa să regăsim echilibrul dintre progresul tehnologic și natura noastră spirituală. Întrebarea este: suntem pregătiți să primim această putere și să o folosim cu înțelepciune?',
    't000013': 'Forța și filosofia în Star Wars',
    't000014': 'Conceptul de Forță este central în universul Star Wars, fiind temelia filosofică și spirituală pe care se sprijină întreaga saga. Acest câmp de energie mistică, ce leagă toate ființele vii, se inspiră din diferite religii și filosofii ale lumii reale, creând un cadru spiritual aparte, care rezonează cu oameni din culturi diferite. Forța este descrisă ca un câmp de energie pretutindeni prezent, creat de toate ființele vii. Înconjoară și pătrunde totul, legând galaxia laolaltă. Ideea seamănă izbitor cu diverse filosofii orientale, mai ales cu „Calea” atotcuprinzătoare din taoism și cu interdependența tuturor ființelor din budism. Forța reprezintă o formă de panteism, sugerând o prezență divină în interiorul și în întreaga natură, nu o divinitate separată, înfățișată ca o persoană.',
    't000057': 'Privind moștenirea de durată a Star Wars, vedem că influența ei depășește cu mult simplul divertisment. Saga este o sursă de inspirație și un punct de pornire pentru discuții, îndemnându-ne să gândim critic despre valorile noastre și despre lumea din jur. Ea ne încurajează să ne imaginăm un viitor mai luminos și ne amintește că, până și în fața unui întuneric copleșitor, speranța și tăria pot învinge. Astfel, Star Wars continuă să lumineze căile pe care le urmăm în propriile vieți, îndemnându-ne să ne folosim capacitatea de schimbare și să năzuim către o galaxie în care binele învinge răul.',
    't000058': 'Bibliografie',
    't000059': 'Star Wars: The Complete Visual Dictionary" de David West Reynolds',
    't000060': '"Star Wars: The Essential Guide to Characters" de Daniel Wallace',
    't000061': '"Star Wars: The Ultimate Visual Guide" de Ryder Windham',
    't000062': '"Star Wars Encyclopedia" de Stephen J. Sansweet',
}
for filename in ('0001.json', '0002.json', '0010.json'):
    path = root / filename
    data = json.loads(path.read_text())
    for segment in data['segments']:
        segment['translation'] = translations[segment['id']]
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
